// Transcribe audio fixtures (tests/fixtures/audio): run with `node scripts/make-audio-fixtures.ts <out dir>`.
// hello.wav: 2 s of a speech-level tone at 44.1 kHz stereo, so decoding, downmixing and resampling to 16 kHz mono
// all run. silence.wav: 2 s of digital silence. (Longer audio is generated by the tests themselves.)
import { mkdirSync, writeFileSync } from 'node:fs';
import { tone, wav } from '../tests/e2e/wav.ts';

const out = process.argv[2] ?? 'tests/fixtures/audio';
mkdirSync(out, { recursive: true });
writeFileSync(`${out}/hello.wav`, wav([tone(2, 44_100, 220), tone(2, 44_100, 330)], 44_100));
writeFileSync(`${out}/silence.wav`, wav([new Float32Array(32_000)], 16_000));
